#include <stdio.h>

int main(void)
{
    char source[] = "CSE212";
    char copy[16];
    size_t n = 0;
    while (source[n] != '\0') {
        copy[n] = source[n];
        n++;
    }
    copy[n] = '\0';
    printf("%s %zu\n", copy, n);
    return 0;
}

#include <stdio.h>
#include <string.h>

void reverse(char text[])
{
    size_t n = strlen(text);
    for (size_t i = 0; i < n / 2; i++) {
        char temp = text[i];
        text[i] = text[n - 1 - i];
        text[n - 1 - i] = temp;
    }
}

int main(void)
{
    char text[] = "CSE";
    reverse(text);
    puts(text);
    return 0;
}

#include <stdio.h>
#include <ctype.h>

int main(void)
{
    char text[] = "Lab 204";
    for (size_t i = 0; text[i] != '\0'; i++) {
        text[i] = (char)toupper((unsigned char)text[i]);
    }
    puts(text);
    return 0;
}

